// @vitest-environment jsdom
import { act, render, screen, waitFor } from "@testing-library/react";
import { beforeEach, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: any) => void>>(),
}));
vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: any) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener() {}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() {
			return { isError: false };
		}
	},
	PostMessageTransport: class {
		async close() {}
	},
}));

beforeEach(() => {
	vi.resetModules();
	bridge.listeners.clear();
	bridge.hostContext = {};
	bridge.connect.mockResolvedValue(undefined);
});

it("review: retries an empty capability restore after late toolInfo", async () => {
	Object.defineProperty(window, "parent", {
		configurable: true,
		value: Object.assign(new EventTarget(), {
			location: { origin: "https://host.test" },
		}),
	});
	let resolveRestore!: (value: any) => void;
	const restore = new Promise<any>((resolve) => {
		resolveRestore = resolve;
	});
	bridge.callServerTool.mockImplementation(async ({ name }: any) =>
		name === "restore_lobu_app_result"
			? restore
			: { isError: false, structuredContent: { saved: true } },
	);
	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data, viewState } = useMcpApp<{ title: string }>();
		return (
			<>
				<span>{data?.title ?? "No result"}</span>
				<span>{String(viewState.open)}</span>
			</>
		);
	}
	render(
		<Provider devMock={{ title: "dev" }}>
			<Probe />
		</Provider>,
	);
	await waitFor(() => expect(bridge.connect).toHaveBeenCalled());
	act(() => {
		for (const handler of bridge.listeners.get("toolresult") ?? []) {
			handler({
				structuredContent: {},
				_meta: { "lobu/mcp-app-snapshot-capability": "cap" },
			});
		}
	});
	await waitFor(() =>
		expect(bridge.callServerTool).toHaveBeenCalledWith({
			name: "restore_lobu_app_result",
			arguments: { snapshot_capability: "cap" },
		}),
	);
	bridge.hostContext = {
		toolInfo: { id: "late-id", tool: { name: "query_sdk" } },
	};
	act(() => {
		for (const handler of bridge.listeners.get("hostcontextchanged") ?? []) {
			handler({ theme: "light" });
		}
	});
	await act(async () => {
		resolveRestore({
			isError: false,
			structuredContent: {
				found: true,
				tool_name: "query_sdk",
				data: { title: "Restored" },
				view_state: { open: true },
			},
		});
		await restore;
	});
	expect(screen.getByText("Restored")).toBeInTheDocument();
});

